let PRE='';const sidx=()=>[...NV.map(n=>({ty:t(["Page","Page","صفحة"]),ti:t(n[1]),r:n[0]})),...N.map(n=>({ty:t(n.tg),ti:t(n.ti),tx:t(n.tx),r:'news',q:t(n.ti)})),...PR.map(p=>({ty:t(["Project","Projet","مشروع"]),ti:t(p.ti),tx:t(p.tx)+' '+t(p.pl),r:'programs'})),...P.map(p=>({ty:'Panda Shop',ti:t(p.n),r:'shop'}))];
function closeS(){$('#sr').hidden=true;$('#sq').setAttribute('aria-expanded','false');if(innerWidth<=1240)$('#sf').classList.remove('sopen')}
function sbTog(){if(innerWidth<=1240){const o=$('#sf').classList.toggle('sopen');o?$('#sq').focus():closeS()}else $('#sq').focus()}
function car(d,id='car'){const c=$('#'+id);c.scrollBy({left:d*(document.documentElement.dir=='rtl'?-1:1)*c.clientWidth*.8,behavior:'smooth'})}
$('#sq').addEventListener('input',()=>{const v=$('#sq').value.trim().toLowerCase(),ul=$('#sr');if(v.length<2){closeS();return}const r=sidx().filter(x=>(x.ti+' '+(x.tx||'')).toLowerCase().includes(v)).slice(0,7);ul.innerHTML=r.length?r.map(x=>`<li><a href="#/${x.r}"${x.q?` data-q="${x.q.replace(/"/g,'&quot;')}"`:''}>${x.ti}<small>${x.ty}</small></a></li>`).join(''):`<li class="no">${t(["No result","Aucun résultat","لا نتيجة"])}</li>`;ul.hidden=false;$('#sq').setAttribute('aria-expanded','true')});
$('#sq').addEventListener('keydown',e=>{if(e.key=='Enter'){e.preventDefault();const a=$('#sr a');if(a)a.click()}else if(e.key=='ArrowDown'){const a=$('#sr a');if(a){e.preventDefault();a.focus()}}else if(e.key=='Escape')closeS()});
$('#sr').addEventListener('keydown',e=>{const a=e.target.closest('a');if(!a)return;if(e.key=='ArrowDown'&&a.parentElement.nextElementSibling){e.preventDefault();a.parentElement.nextElementSibling.querySelector('a').focus()}if(e.key=='ArrowUp'){e.preventDefault();const p=a.parentElement.previousElementSibling;p?p.querySelector('a').focus():$('#sq').focus()}if(e.key=='Escape'){closeS();$('#sq').focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('#sf'))closeS();const a=e.target.closest('a[data-q]');if(a){PRE=a.dataset.q;closeS();if(location.hash=='#/news')setTimeout(route)}});
addEventListener('scroll',()=>$('#hd').classList.toggle('hs',scrollY>8),{passive:true});
const RM=matchMedia('(prefers-reduced-motion:reduce)').matches;
function cntUp(el){const m=el.textContent.match(/^(\D*)([\d\s]+)(.*)$/);if(!m||RM)return;const n=+m[2].replace(/\s/g,''),t0=performance.now(),f=x=>(x).toLocaleString('fr-FR');const st=p=>{const k=Math.min(1,(p-t0)/1400);el.textContent=m[1]+f(Math.round(n*(1-Math.pow(1-k,3))))+m[3];if(k<1)requestAnimationFrame(st);else el.textContent=m[0]};requestAnimationFrame(st)}
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');const b=e.target.matches('.kpis li')&&e.target.querySelector('b');if(b)cntUp(b);io.unobserve(e.target)}}),{threshold:.12});
function reveal(){document.querySelectorAll('#main h2,#main .card,#main .person,#main .ic,#main .kpis li,#main .rvb,#main .sp,#main .dom,#main .pcard,#main .shd>.dec,#main .pb .wrap>*').forEach((e,i)=>{e.style.setProperty('--d',(i%4)*70+'ms');e.classList.add('rv');io.observe(e)})}
