const NL_ENDPOINT='';
async function nlSub(f){const g=i=>$('#'+i).value.trim(),s=$('#nls'),e=$('#nle');s.className='nls full';const bad=m=>{s.textContent=t(m);s.classList.add('err')};
if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(g('nle'))){e.setAttribute('aria-invalid','true');e.focus();return bad(["Please enter a valid email address.","Veuillez saisir une adresse e-mail valide.","يرجى إدخال بريد إلكتروني صالح."])}
e.removeAttribute('aria-invalid');if(!$('#nlc').checked){$('#nlc').focus();return bad(["Please tick the consent box.","Veuillez cocher la case de consentement.","يرجى تحديد خانة الموافقة."])}
const d={first:g('nlf'),last:g('nll'),email:g('nle'),phone:g('nlp'),lang};
if(NL_ENDPOINT){try{const r=await fetch(NL_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});if(!r.ok)throw 0;f.reset();s.textContent=t(["Thank you for subscribing!","Merci pour votre inscription !","شكراً لاشتراكك!"]);s.classList.add('ok')}catch(x){bad(["Something went wrong. Please try again.","Une erreur est survenue. Réessayez.","حدث خطأ. حاول مجدداً."])}return}
location.href='mailto:contact@wwfna.org?subject='+encodeURIComponent('Newsletter subscription')+'&body='+encodeURIComponent(`${d.first} ${d.last}\n${d.email}\n${d.phone}\n(${lang})`);s.textContent=t(["Almost done: send the email that just opened to confirm your subscription.","Presque fini : envoyez l'e-mail qui vient de s'ouvrir pour confirmer votre inscription.","شارفنا على الانتهاء: أرسل البريد الذي فُتح للتو لتأكيد اشتراكك."]);s.classList.add('ok')}
const GRM_EMAIL='grm.contact@wwfna.org';
const grm=()=>{return `<div class="grm"><h2>${t(["Grievance Redress Mechanism","Mécanisme de traitement des plaintes","آلية معالجة الشكاوى"])}</h2>
<p>${t(["WWF North Africa is committed to upholding transparency, accountability and integrity in all of its activities and partnerships in the region. The “Grievance Redress Mechanism” is a core institutional tool that gives local communities, partners, beneficiaries and the general public access to safe and trusted channels to voice their concerns or submit suggestions, in order to build constructive dialogue and continuously improve the quality of our projects.","WWF Afrique du Nord s'engage à faire respecter les principes de transparence, de redevabilité et d'intégrité dans l'ensemble de ses activités et partenariats dans la région. Le « mécanisme de traitement des plaintes » est un outil institutionnel essentiel qui offre aux communautés locales, aux partenaires, aux bénéficiaires et au grand public des canaux sûrs et fiables pour exprimer leurs préoccupations ou formuler des propositions, afin de nourrir un dialogue constructif et d'améliorer en continu la qualité des projets.","يلتزم الصندوق العالمي للطبيعة لشمال أفريقيا بترسيخ مبادئ الشفافية، والمساءلة، والنزاهة في كافة أنشطه وشراكاته في المنطقة. وتُعد \"آلية معالجة الشكاوى\" أداة مؤسسية أساسية تتيح للمجتمعات المحلية، والشركاء، والمستفيدين، وعموم الجمهور الوصول إلى قنوات آمنة وموثوقة للتعبير عن مخاوفهم أو تقديم مقترحاتهم لبناء حوار بنّاء وتطوير جودة المشاريع باستمرار."])}</p>
<p>${t(["To make the process easier and ensure a quick response, please 📥 ","Pour faciliter le traitement et garantir une réponse rapide, veuillez 📥 ","ولضمان تيسير هذه العملية وسرعة الاستجابة لها، يرجى 📥 "])}<a href="#/grievance" data-dl="form">${t(["click here","cliquer ici","الضغط هنا"])}</a>${t([" to download the official complaint form, fill it in and send it directly by email to: "," pour télécharger le formulaire officiel de plainte, le remplir et l'envoyer directement par e-mail à l'adresse suivante : "," لتحميل نموذج الشكاوى الرسمي، ومن ثمّ تعبئته وإرساله مباشرة عبر البريد الإلكتروني إلى العنوان التالي: "])}<a dir="ltr" href="mailto:${GRM_EMAIL}">${GRM_EMAIL}</a></p>
<p>${t(["Once your request is received, the file will be carefully registered and screened, followed by a thorough investigation conducted in strict confidence and with full seriousness, in order to take the necessary corrective action and provide you with official replies as soon as possible.","Dès réception de votre demande, le dossier sera enregistré avec soin et fera l'objet d'un tri préliminaire, suivi d'une enquête approfondie menée dans la plus stricte confidentialité et avec le plus grand sérieux, afin de prendre les mesures correctives nécessaires et de vous apporter des réponses officielles dans les meilleurs délais.","وفور استلام طلبكم، سيخضع الملف لعملية تسجيل دقيقة وفرز أولي يتبعها تحقيق شامل يتسم بالسرية التامة والجدية المطلقة، بهدف اتخاذ الإجراءات التصحيحية اللازمة وموافاتكم بالردود الرسمية في أسرع وقت ممكن."])}</p></div>`};

const GDL=[["form",["Complaint form (FR · EN · AR)","Formulaire de plainte (FR · EN · AR)","استمارة الشكوى (FR · EN · AR)"]],["grm",["Grievance Mechanism document (EN)","Document du mécanisme de plaintes (EN)","وثيقة آلية التظلم (EN)"]]];
const GOBJ=[["strengthen trust between WWF-NA and its stakeholders", "renforcer la confiance entre WWF-NA et ses parties prenantes", "تعزيز الثقة بين الصندوق وأصحاب المصلحة"],["encourage open dialogue and constructive participation", "encourager le dialogue ouvert et la participation constructive", "تشجيع الحوار المفتوح والمشاركة البنّاءة"],["continuously improve the quality and impact of projects and programs", "améliorer en continu la qualité et l'impact des projets et programmes", "التحسين المستمر لجودة المشاريع والبرامج وأثرها"]];
const GCH=[[["By e-mail", "Par e-mail", "عبر البريد الإلكتروني"],'<a dir="ltr" href="mailto:'+GRM_EMAIL+'">'+GRM_EMAIL+'</a>'],[["By post", "Par courrier postal", "عبر البريد"],"3 rue El Moez, El Menzah 1, 1004 Tunis, Tunisia"],[["Online contact form", "Formulaire de contact en ligne", "نموذج الاتصال عبر الإنترنت"],["Through the WWF-NA online contact form.", "Via le formulaire de contact en ligne de WWF-NA.", "عبر نموذج الاتصال الإلكتروني للصندوق."]],[["QR code", "Code QR", "رمز الاستجابة السريعة"],["The grievance form is accessible through the QR code on WWF-NA communication materials, to be completed and sent to the e-mail address above.", "Le formulaire est accessible via le code QR présent sur les supports de communication de WWF-NA, à remplir et à envoyer à l'adresse e-mail ci-dessus.", "تتوفر استمارة الشكوى عبر رمز الاستجابة السريعة على مواد التواصل، وتُعبّأ وتُرسل إلى البريد الإلكتروني أعلاه."]],[["Social media", "Réseaux sociaux", "وسائل التواصل الاجتماعي"],["Not encouraged for filing complaints. A complaint received by direct message or tag is acknowledged and redirected to the official channels; WWF-NA does not respond publicly.", "Déconseillés pour déposer une plainte. Une plainte reçue par message direct ou mention est reconnue puis redirigée vers les canaux officiels ; WWF-NA ne répond pas publiquement.", "لا يُشجَّع على تقديم الشكاوى عبرها. تُقرّ الشكوى الواردة برسالة مباشرة أو إشارة ثم تُحوَّل إلى القنوات الرسمية، ولا يردّ الصندوق علناً."]],[["Directly to staff", "Directement auprès du personnel", "مباشرة لدى الموظفين"],["Raised during an event, workshop or training. Staff must escalate it to the relevant WWF-NA team.", "Formulée lors d'un événement, d'un atelier ou d'une formation. Le personnel doit la transmettre à l'équipe concernée de WWF-NA.", "تُقدَّم خلال فعالية أو ورشة أو تدريب، ويجب على الموظفين إحالتها إلى الفريق المعني."]],[["EthicsPoint", "EthicsPoint", "نظام EthicsPoint"],["For serious complaints: fraud, corruption, discrimination, community concerns about WWF projects, human-rights abuse. Secure and confidential, anonymous or named, in any language.", "Pour les plaintes graves : fraude, corruption, discrimination, préoccupations communautaires liées aux projets WWF, atteintes aux droits humains. Sûr et confidentiel, anonyme ou nominatif, dans toute langue.", "للشكاوى الجسيمة: احتيال، فساد، تمييز، مخاوف المجتمعات بشأن مشاريع الصندوق، انتهاكات حقوق الإنسان. نظام آمن وسري، باسم أو دون اسم، بأي لغة."]]];
const GST=[[["Reception", "Réception", "الاستلام"],["By e-mail, online form, QR code, post, phone, social media or in person. Anonymous complaints are accepted.", "Par e-mail, formulaire en ligne, code QR, courrier, téléphone, réseaux sociaux ou en personne. Les plaintes anonymes sont acceptées.", "عبر البريد الإلكتروني أو النموذج أو رمز QR أو البريد أو الهاتف أو وسائل التواصل أو شخصياً. الشكاوى المجهولة مقبولة."]],[["Registration and acknowledgement", "Enregistrement et accusé de réception", "التسجيل والإشعار بالاستلام"],["Each complaint receives a unique reference number in the GRM register. An acknowledgement is sent, if contact details are given, within 15 working days at most.", "Chaque plainte reçoit un numéro de référence unique dans le registre du mécanisme. Un accusé de réception est envoyé, si des coordonnées sont fournies, sous 15 jours ouvrables au maximum.", "تحصل كل شكوى على رقم مرجعي فريد في سجل الآلية. يُرسل إشعار بالاستلام، إذا قُدّمت بيانات الاتصال، في أجل أقصاه 15 يوم عمل."]],[["Initial screening", "Examen préliminaire", "الفرز الأولي"],["The GRM focal point checks admissibility, urgency and whether the issue is environmental, social, governance or human rights. Out-of-scope complaints are redirected to the right channel.", "Le point focal du mécanisme vérifie la recevabilité, l'urgence et la nature (environnementale, sociale, gouvernance ou droits humains). Les plaintes hors champ sont réorientées vers le bon canal.", "يفحص المسؤول المعني بالآلية قبول الشكوى ومدى استعجالها وطبيعتها (بيئية أو اجتماعية أو حوكمة أو حقوق إنسان). وتُحوَّل الشكاوى الخارجة عن النطاق إلى القناة المناسبة."]],[["Assessment and investigation", "Évaluation et enquête", "التقييم والتحقيق"],["A designated team gathers facts, consults stakeholders and protects confidentiality. The file is shared with the Senior Management Team for follow-up.", "Une équipe désignée recueille les faits, consulte les parties prenantes et garantit la confidentialité. Le dossier est transmis à l'équipe de direction pour suivi.", "يجمع فريق مكلَّف الوقائع ويستشير أصحاب المصلحة ويضمن السرية، ويُحال الملف إلى فريق الإدارة العليا للمتابعة."]],[["Resolution and response", "Résolution et réponse", "الحل والرد"],["A corrective action plan or mediation is proposed. The complainant is informed of the findings and measures within 45 working days, or longer if the case requires it.", "Un plan d'actions correctives ou une médiation est proposé. Le plaignant est informé des conclusions et des mesures sous 45 jours ouvrables, ou plus si le dossier l'exige.", "يُقترح خطة إجراءات تصحيحية أو وساطة. يُبلَّغ المشتكي بالنتائج والتدابير في غضون 45 يوم عمل، أو أكثر إذا تطلبت القضية ذلك."]],[["Follow-up and closure", "Suivi et clôture", "المتابعة والإغلاق"],["Implementation is monitored and documented. Once resolved, the case is closed and archived, and lessons learned are shared internally.", "La mise en œuvre est suivie et documentée. Une fois résolu, le dossier est clôturé et archivé, et les enseignements sont partagés en interne.", "يُتابَع التنفيذ ويُوثَّق. وبعد الحل تُغلق القضية وتُؤرشف وتُشارك الدروس المستفادة داخلياً."]]];
async function dlDoc(k){if(DOCS[k].u){const a=document.createElement('a');a.href=DOCS[k].u;a.download=DOCS[k].n;document.body.appendChild(a);a.click();a.remove();return}const f=DOCS[k],bin=atob(f.d),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const blob=new Blob([u],{type:'application/pdf'});
try{const d=window.claude?await claude.use('downloads'):null;if(d){await d.save({filename:f.n,data:blob});return}}catch(e){if(e&&e.code=='declined')return}
const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=f.n;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}
document.addEventListener('click',e=>{const a=e.target.closest('[data-dl]');if(a){e.preventDefault();dlDoc(a.dataset.dl)}});
let first=true;function route(){let p=location.hash.slice(2)||'home';if(!Pg[p])p='home';if(MP){MP.remove();MP=null}$('#main').innerHTML=Pg[p]()+(['home','checkout','done'].includes(p)?'':ctaB());$('#main').dataset.p=p;chrome();if(p=='programs')initPrj();reveal();const mm=$('#main');mm.classList.remove('pgin');void mm.offsetWidth;mm.classList.add('pgin');$('#nav').classList.remove('open');$('#bg').setAttribute('aria-expanded','false');if(p=='news'){$('#nq').value=PRE;PRE='';nlist();$('#nf').addEventListener('input',nlist);$('#nf').addEventListener('reset',()=>setTimeout(nlist))}
document.title=(({home:U.h1,about:U.nav[0],team:["Team","Équipe","الفريق"],grievance:["Grievance mechanism","Mécanisme de plaintes","آلية التظلم"],programs:U.nav[1],shop:U.nav[2],checkout:["Checkout","Commander","الطلب"],done:["Order","Commande","الطلب"],news:U.nav[3],involved:U.nav[4],corporate:U.nav[5]})[p]?t(({home:U.h1,about:U.nav[0],team:["Team","Équipe","الفريق"],grievance:["Grievance mechanism","Mécanisme de plaintes","آلية التظلم"],programs:U.nav[1],shop:U.nav[2],checkout:["Checkout","Commander","الطلب"],done:["Order","Commande","الطلب"],news:U.nav[3],involved:U.nav[4],corporate:U.nav[5]})[p]):'')+' – WWF Tunisia';
if(!first){scrollTo(0,0);const h=$('#main h1');if(h)h.focus({preventScroll:true})}first=false}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.l){lang=b.dataset.l;li={en:0,fr:1,ar:2}[lang];route();$('#live').textContent=b.getAttribute('aria-label')}
else if(b.dataset.add){cart[b.dataset.add]=(cart[b.dataset.add]||0)+1;chrome();$('#live').textContent=t(["Added to cart","Ajouté au panier","أضيف إلى السلة"])}
else if(b.dataset.sc!==undefined){prjF=+b.dataset.sc;prjRender()}else if(b.dataset.pj){openPj(+b.dataset.pj)}else if(b.id=='sb'){sbTog()}else if(b.dataset.car){car(+b.dataset.car,b.dataset.t)}else if(b.id=='pz'){const p=b.getAttribute('aria-pressed')!='true';b.setAttribute('aria-pressed',p);$('.nw').classList.toggle('pz',p)}else if(b.dataset.cat){shopCat=b.dataset.cat;route()}
else if(b.dataset.q){const[i,d]=b.dataset.q.split(':');cart[i]=Math.max(0,(cart[i]||0)+ +d);if(!cart[i])delete cart[i];route()}
else if(b.id=='bg'){const o=$('#nav').classList.toggle('open');b.setAttribute('aria-expanded',o)}});
document.addEventListener('submit',e=>{if(e.target.id=='of'){e.preventDefault();cart={};location.hash='#/done'}
if(e.target.id=='nlform'){e.preventDefault();nlSub(e.target)}if(e.target.id=='gf'){e.preventDefault();location.href='mailto:'+GRM_EMAIL+'?subject='+encodeURIComponent('Grievance')+'&body='+encodeURIComponent(['g1','g2','g3','g4'].map(i=>$('#'+i).value).join('\n'))}});
document.addEventListener('keydown',e=>{if(e.key=='Escape'&&$('#nav').classList.contains('open')){$('#nav').classList.remove('open');$('#bg').setAttribute('aria-expanded','false');$('#bg').focus()}});
addEventListener('hashchange',route);route();
